function reverseText(s, opts){
  opts=opts||{}; var t=String(s||'');
  if(opts.byLine) return t.split(/\r?\n/).map(function(L){ return L.split('').reverse().join(''); }).join('\n');
  return t.split('').reverse().join('');
}

var EXPORTS={reverseText:reverseText};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
